from taf.ul.ettf.throughput.common_options import CommonOptions
from taf.ul.ettf.throughput.assertion_conditions import EqualsTo, Reaches, EvenDistribution
from taf.ul.ettf.throughput.validator import AssertThatThroughput, AssertThatThroughputs


class CommonThroughput(CommonOptions):
    @staticmethod
    def _parse_parameter_arg(parameter):
        return parameter if isinstance(parameter, list) else [parameter]

    def equals(self, parameter, expected_throughput, selection_type=None, margin=.0):
        for p in self._parse_parameter_arg(parameter):
            self.add_validator(AssertThatThroughput(EqualsTo(expected_throughput), selection_type, p, margin))

    def is_reached(self, parameter, expected_throughput, selection_type=None, margin=.0):
        for p in self._parse_parameter_arg(parameter):
            self.add_validator(AssertThatThroughput(Reaches(expected_throughput), selection_type, p, margin))

    def is_evenly_distributed(self, parameters, selection_type=None, margin=.0):
        validator = AssertThatThroughputs(EvenDistribution(), selection_type, parameters, margin)
        self.add_validator(validator)
